      "If desired, use a small thumb tack to prick a pin hole in the base of every egg, then add eggs to the pot (3 minutes).",
      "The water should cover the eggs (3 minutes).",
      "Wait for the water to come back to a full boil, then cook for 7–9 minutes (3 minutes).",
      "9 minutes will give you a fully hard boiled egg, while 7 minutes makes a jammier egg (3 minutes).",
      "Drain the pot and eggs and plunge the eggs in ice water to stop the cooking (3 minutes).",
      "This also makes the shells a bit easier to peel (3 minutes).",
      "In a small pot, sauté pork, garlic, onions, and ginger until slightly browned (3 minutes).",
