    "name": "Zacusca (Romanian Vegetable Spread)",
    "minutes": 45,
    "servings": 4,
    "tags": [
      "dinner",
      "medium",
      "moderate",
      "vegetarian"
    ],
    "ingredients": [
      {
        "qty": 3,
        "unit": "kg",
        "item": "medium-large eggplant (any variety)"
      },
      {
        "qty": 500,
        "unit": "g",
        "item": "onion, finely chopped or grated"
      },
      {
        "qty": 1,
        "unit": "kg",
        "item": "red bell pepper of the gogoșar variety"
      },
      {
        "qty": 1,
        "unit": "kg",
        "item": "bell pepper"
      },
      {
        "qty": 200,
        "unit": "g",
        "item": "tomato paste"
      },
      {
        "qty": 3,
        "unit": "tbsp",
        "item": "salt"
      },
      {
        "qty": 700,
        "unit": "ml",
        "item": "sunflower oil"
      },
      {
        "qty": 20,
        "unit": "",
        "item": "dried black peppercorns"
      },
      {
        "qty": 4,
        "unit": "",
        "item": "–6 dried bay leaves"
      }
    ],
    "steps": [
      "Roast the eggplants and peppers until their skins are charred and easily removable by hand (3 minutes).",
      "Skin the vegetables (3 minutes).",
      "The pepper skins should come off easily in long strips (3 minutes).",
      "The eggplant skin might retain some of the flesh; some people like to take the back of the knife over the skin to remove that flesh and use it because it has a smokey flavor, but you can easily discard it if pressed for time (3 minutes).",
      "Dice the eggplants and peppers in 1–2 cm cubes (3 minutes).",
      "The peppers will retain their shape, but the eggplant flesh is mushy so don't worry if your cubes aren't perfect shapes, they will disintegrate more when cooking and that is the goal (3 minutes).",
      "In a large nonstick skillet, sauté the onions in the oil over medium until golden (3 minutes).",
      "Add the peppers to the onions (3 minutes).",
      "Cook for 15 minutes, stirring occasionally (3 minutes).",
      "Make sure it doesn't stick to the bottom of the pan and burn (3 minutes).",
      "Stir in the eggplants, tomato paste, bay leaves, salt, and peppercorns (3 minutes).",
      "Simmer until the oil comes to the surface."
    ],
